import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Texture, Color, PointLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- text bridging idiom ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleText = items.find((i) => i.role === 'title')?.text ?? 'Features';
  const metaText = items.find((i) => i.role === 'meta')?.text ?? 'SECTION';

  const root = new Group();
  root.name = 'features-list-row';

  const inner = new Group();
  root.add(inner);

  const ROW_W = 3.1;
  const ROW_H = 0.56;

  // ---- background parallax-displacement card ----
  const colorTex = new Texture();
  const depthTex = new Texture();

  const cardMat = new MeshStandardNodeMaterial();
  cardMat.map = colorTex;
  cardMat.roughness = 0.6;
  cardMat.metalness = 0.3;
  cardMat.clearcoat = 0.12;
  cardMat.color = new Color(colors.ink);

  const displaceAmt = uniform(0.035);
  cardMat.positionNode = positionLocal.add(
    normalLocal.mul(texture(depthTex, uv()).r.mul(displaceAmt))
  );

  const cardGeo = new PlaneGeometry(ROW_W, ROW_H, 64, 64);
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.name = 'row-card';
  cardMesh.position.set(0, 0, 0);
  inner.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorTex.image = tex.image;
    colorTex.colorSpace = tex.colorSpace;
    colorTex.needsUpdate = true;
    cardMat.needsUpdate = true;
  }).catch(() => {});

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex.image = tex.image;
      depthTex.needsUpdate = true;
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- subtle divider ----
  const dividerGeo = new PlaneGeometry(ROW_W * 0.94, 0.012, 1, 1);
  const dividerMat = new MeshStandardNodeMaterial();
  dividerMat.color = new Color(colors.paper);
  dividerMat.roughness = 0.9;
  dividerMat.metalness = 0.0;
  dividerMat.transparent = true;
  dividerMat.opacity = 0.16;
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -ROW_H / 2 + 0.03, 0.012);
  inner.add(divider);

  // ---- title text ----
  const titleNode = ctx.fontAtlas.createText(titleText, {
    fontSize: 30,
    color: colors.paper,
    align: 'left',
  });
  titleNode.position.set(-ROW_W / 2 + 0.28, 0.05, 0.02);
  inner.add(titleNode);

  // ---- meta text ----
  const metaNode = ctx.fontAtlas.createText(metaText, {
    fontSize: 13,
    color: '#aab0bd',
    align: 'right',
    letterSpacingPx: 1.2,
  });
  metaNode.position.set(ROW_W / 2 - 0.28, 0.05, 0.02);
  inner.add(metaNode);

  // ---- accent edge (focus/hover indicator) ----
  const accentGeo = new PlaneGeometry(0.035, ROW_H * 0.82, 1, 1);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.color = new Color(colors.accent);
  accentMat.emissive = new Color(colors.accent);
  accentMat.emissiveIntensity = 0.0;
  accentMat.roughness = 0.5;
  accentMat.metalness = 0.2;
  const accentEdge = new Mesh(accentGeo, accentMat);
  accentEdge.position.set(-ROW_W / 2 + 0.01, 0, 0.03);
  inner.add(accentEdge);

  const accentLight = new PointLight(new Color(colors.accent), 0, 1.2, 2);
  accentLight.position.set(-ROW_W / 2, 0, 0.4);
  inner.add(accentLight);

  // ---- required subtle parallax primitive (render mode: parallax-plane) ----
  let parallaxHandle = null;
  try {
    parallaxHandle = ctx.primitives['parallax-scroll'](cardMesh, {
      trigger: 'scroll',
      strength: 0.05,
      axis: 'xy',
    });
  } catch (e) {
    parallaxHandle = null;
  }

  // ---- applied cinematic primitives from config (none expected, but honor contract) ----
  const appliedPrimitives = [];
  const primList = config.cinematicPrimitives ?? [];
  for (const prim of primList) {
    try {
      const handle = ctx.primitives[prim.name](inner, prim.params ?? {});
      appliedPrimitives.push(handle);
    } catch (e) {
      // ignore unknown primitive failures
    }
  }

  // ---- motion state ----
  const baseY = 0;
  let hoverTl = null;
  let pressTl = null;

  function onPointerOver() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(inner.position, { y: baseY + 0.15, duration: 0.6, ease: 'power3.out' }, 0);
    hoverTl.to(accentMat, { emissiveIntensity: 1.6, duration: 0.35, ease: 'power2.out' }, 0);
    hoverTl.to(accentLight, { intensity: 1.0, duration: 0.35, ease: 'power2.out' }, 0);
    hoverTl.to(cardMat.color, {
      r: new Color(colors.ink).r * 1.08,
      g: new Color(colors.ink).g * 1.08,
      b: new Color(colors.ink).b * 1.08,
      duration: 0.4,
      ease: 'power2.out',
    }, 0);
  }

  function onPointerOut() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(inner.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    hoverTl.to(accentMat, { emissiveIntensity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(accentLight, { intensity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    const baseC = new Color(colors.ink);
    hoverTl.to(cardMat.color, { r: baseC.r, g: baseC.g, b: baseC.b, duration: 0.4, ease: 'power2.out' }, 0);
  }

  function onPointerDown() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(inner.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  }

  function onPointerUp() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power3.out' });
  }

  function onClick() {
    onPointerDown();
    gsap.delayedCall(0.13, () => {
      onPointerUp();
      ctx.emit('hub-features.select', { itemId: 'hub-features' });
      ctx.emit('navigate', { to: 'hub-features' });
    });
  }

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerEnter: onPointerOver,
    onPointerLeave: onPointerOut,
    onHoverStart: onPointerOver,
    onHoverEnd: onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
    onPress: onPointerDown,
    onRelease: onPointerUp,
  };

  root.userData.cleanup = function cleanup() {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();

    if (parallaxHandle && typeof parallaxHandle.cleanup === 'function') {
      parallaxHandle.cleanup();
    }
    for (const h of appliedPrimitives) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }

    cardGeo.dispose();
    cardMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    colorTex.dispose();
    depthTex.dispose();

    if (titleNode?.geometry) titleNode.geometry.dispose?.();
    if (titleNode?.material) titleNode.material.dispose?.();
    if (metaNode?.geometry) metaNode.geometry.dispose?.();
    if (metaNode?.material) metaNode.material.dispose?.();

    inner.clear();
    root.clear();
  };

  return root;
}
